def on_off(names, named=False):
    """Templates for switching each of `names` on and off; `named` also passes the name as the `name` parameter."""
    on = ["turn on {n}", "turn {n} on", "enable {n}", "switch on {n}", "switch {n} on", "activate {n}", "i need {n} on", "{n} on"]
    off = ["turn off {n}", "turn {n} off", "disable {n}", "switch off {n}", "switch {n} off", "shut off {n}", "{n} off", "i don't need {n}"]
    return [(t.format(n=n), {"state": state, **({"name": n} if named else {})})
            for state, templates in (("on", on), ("off", off)) for t in templates for n in names]


def plain(*phrases):
    return [(phrase, {}) for phrase in phrases]


